window.docContents[197].resolve({"/#while-loops":{"contents":"When programming with local mutability, while loops can be a convenient alternative to repeat with an if-guarded break:\n\n\n\nBehind the scenes, while is just a simpler notation for repeat.\n\n\n","context":"Functional Programming in Lean\u0009Monad Transformers\u0009Additional Conveniences","header":"6.5.3. While Loops","id":"/#while-loops"}});